  return instance_object_->trusted_data(instance_object_->GetIsolate())
      ->dispatch_table_for_imports()
      ->target(index_);
}

void ImportedFunctionEntry::set_target(Address new_target) {
  return instance_object_->trusted_data(instance_object_->GetIsolate())
      ->dispatch_table_for_imports()
      ->SetTarget(index_, new_target);
}

